// 5.2 (P1/P2, field report "detalles constructivos"): verify on paper - viewport ink, printed gray,
// printed lines per note, before/after comparison, font advice - and the sheet rules around them.
// Every PDF here is generated by the test.
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using Horizun.Revit.Core;
using Newtonsoft.Json.Linq;
using UglyToad.PdfPig.Core;
