using UglyToad.PdfPig.Writer;
using Xunit;

namespace Horizun.Core.Tests
{
    public class PdfPaperTests
    {
        private const double Pt = 72.0 / 25.4;

        private static string Temp() => Path.Combine(Path.GetTempPath(), "hz-paper-" + Guid.NewGuid().ToString("N") + ".pdf");

        private static PdfDrawOp Rect(double x0, double y0, double x1, double y1, double fillDark)
            => new PdfDrawOp
            {
                Fill = true, FillDark = fillDark, Box = new[] { x0, y0, x1, y1 },
                Rings = { new List<double[]> { new[] { x0, y0 }, new[] { x1, y0 }, new[] { x1, y1 }, new[] { x0, y1 } } }, Closed = { true }
            };

        // ---- printed gray ----------------------------------------------------------------------

        [Fact]
        public void A_black_fill_over_half_the_region_reads_half_dark_and_half_inked()
        {
            var ops = new List<PdfDrawOp> { Rect(0, 0, 50, 100, 1.0) };
            JObject g = PdfQaPaper.Gray(ops, null, null, new[] { 0.0, 0, 100, 100 }, 0.1);
            Assert.Equal(0.5, g.Value<double>("mean_darkness"), 2);
            Assert.Equal(0.5, g.Value<double>("inked_fraction"), 2);
            Assert.Equal(0.5, g["histogram"][9].Value<double>(), 2);
            Assert.Equal(0.5, g["histogram"][0].Value<double>(), 2);
            Assert.Contains("cells under text", g.Value<string>("limits"));
        }

        [Fact]
        public void A_later_white_fill_masks_what_is_under_it_as_on_paper()
        {
            var ops = new List<PdfDrawOp> { Rect(0, 0, 100, 100, 1.0), Rect(0, 0, 100, 100, 0.0) };
            Assert.Equal(0.0, PdfQaPaper.Gray(ops, null, null, new[] { 0.0, 0, 100, 100 }, 0.1).Value<double>("mean_darkness"), 3);
        }

        [Fact]
        public void A_hairline_stroke_darkens_about_its_own_area_not_a_whole_cell_band()
        {
            // 0.25 pt line, 100 pt long, across a 100 x 100 pt region: ink area 25 of 10000 = 0.0025.
            var line = new PdfDrawOp { Stroke = true, StrokeDark = 1, Width = 0.25, Box = new[] { 0.0, 50, 100, 50 },
                Rings = { new List<double[]> { new[] { 0.0, 50 }, new[] { 100.0, 50 } } }, Closed = { false } };
            double mean = PdfQaPaper.Gray(new List<PdfDrawOp> { line }, null, null, new[] { 0.0, 0, 100, 100 }, 0.1).Value<double>("mean_darkness");
            Assert.InRange(mean, 0.0015, 0.0045);
        }

        [Fact]
        public void An_even_odd_ring_inside_a_ring_is_a_hole()
        {
            var op = Rect(0, 0, 100, 100, 1.0);
            op.EvenOdd = true;
            op.Rings.Add(new List<double[]> { new[] { 25.0, 25 }, new[] { 75.0, 25 }, new[] { 75.0, 75 }, new[] { 25.0, 75 } });
            op.Closed.Add(true);
            Assert.Equal(0.75, PdfQaPaper.Gray(new List<PdfDrawOp> { op }, null, null, new[] { 0.0, 0, 100, 100 }, 0.1).Value<double>("mean_darkness"), 2);
        }

        [Fact]
        public void Images_are_excluded_from_the_tone_and_counted()
        {
            JObject g = PdfQaPaper.Gray(new List<PdfDrawOp>(), new List<double[]> { new[] { 0.0, 0, 100, 50 } }, null, new[] { 0.0, 0, 100, 100 }, 0.1);
            Assert.Equal(0.5, g.Value<double>("image_fraction"), 2);
            Assert.Equal(0.0, g.Value<double>("mean_darkness"), 3);
        }

        [Fact]
        public void A_real_pdf_gray_fill_reads_back_as_its_gray_inside_a_region()
        {
            var builder = new PdfDocumentBuilder();
            PdfPageBuilder page = builder.AddPage(595, 842);
            page.SetTextAndFillColor(128, 128, 128);
            page.DrawRectangle(new PdfPoint(100, 100), 200, 100, 1, true);
            string path = Temp();
            try
            {
                File.WriteAllBytes(path, builder.Build());
                var region = new JObject { ["name"] = "hatch", ["rect_mm"] = new JArray(110 / Pt, 110 / Pt, 290 / Pt, 190 / Pt) };
                var o = PdfQa.Parse(new JObject { ["regions"] = new JArray(region) }, out string e);
                Assert.Null(e);
                JObject report = PdfQa.Inspect(path, o);
                JObject g = (JObject)report["ink"][0]["regions"][0]["gray"];
                Assert.True(g.Value<bool>("measured"));
                Assert.Equal(1 - 128 / 255.0, g.Value<double>("mean_darkness"), 2);
                Assert.Equal(1.0, g.Value<double>("inked_fraction"), 2);
            }
            finally { if (File.Exists(path)) File.Delete(path); }
        }

        // ---- viewport ink ------------------------------------------------------------------------

        [Theory]
        [InlineData("0 g", "S")]
        [InlineData("0 g", "B*")]
        [InlineData("1 g", "B")]
        public void Disjoint_strokes_in_a_pdf_path_keep_the_moving_viewport_ink_separate_from_the_sheet(string fill, string paint)
        {
            JObject Measure(double dx, double dy)
            {
                string content = FormattableString.Invariant(
                    $"{fill} 0 G {(388 + dx) * Pt:F6} {(280 + dy) * Pt:F6} {20 * Pt:F6} {40 * Pt:F6} re {466 * Pt:F6} {295 * Pt:F6} {8 * Pt:F6} {5 * Pt:F6} re {paint}");
                var page = ReadContentStream(content, captureDrawing: true);
                Assert.Equal(2, Assert.Single(page.Drawing).Rings.Count);
                Assert.Equal(2, page.Marks.Count);
                Assert.Single(page.Ink);
                var map = new PdfSheetMap { Page = 1, OutlineMm = new[] { 0.0, 0, 840, 594 } };
                map.Viewports.Add(new PdfViewportBox
                {
                    ViewportId = 1,
                    BoxMm = new[] { 370 + dx, 270 + dy, 430 + dx, 330 + dy }
                });
                return (JObject)PdfQaPaper.ViewportInk(page, map)[0];
            }

            JObject before = Measure(0, 0);
            double[] offset = before["ink_from_box_center_mm"].Values<double>().ToArray();
            double dx = 420 - (400 + (offset[0] + offset[2]) / 2);
            double dy = 297 - (300 + (offset[1] + offset[3]) / 2);
            JObject after = Measure(dx, dy);

            Assert.Equal(1, after.Value<int>("ink_items"));
            Assert.Equal(new[] { 410.0, 277, 430, 317 }, after["ink_mm"].Values<double>());
        }

        [Fact]
        public void A_compound_path_consumes_the_mark_limit_one_subpath_at_a_time()
        {
            var content = new StringBuilder("1100 800 10 10 re S\n");
            for (int i = 0; i < 20000; i++) content.Append("1100 800 m 1110 810 l\n");
            content.Append("S\n1120 810 10 10 re S");
            var page = ReadContentStream(content.ToString(), captureDrawing: true);

            Assert.Equal(20000, page.Marks.Count);
            Assert.Equal(3, page.Ink.Count);
            Assert.True(page.MarksTruncated);
            Assert.False(page.DrawingTruncated);
            Assert.Equal(3, page.Drawing.Count);
            var map = new PdfSheetMap { Page = 1, OutlineMm = new[] { 0.0, 0, 840, 594 } };
            map.Viewports.Add(new PdfViewportBox { ViewportId = 1, BoxMm = new[] { 370.0, 270, 430, 330 } });
            JObject report = PdfQa.Judge(new[] { page }, new PdfQaOptions { Viewports = true, SheetMaps = { map } });
            Assert.Equal("partial", report.Value<string>("verdict"));
            Assert.Contains(report["incomplete"].Values<string>(), reason => reason.Contains("viewport ink exceeded"));
            var row = (JObject)Assert.Single((JArray)report["viewports"]["items"]);
            Assert.Equal(20000, row.Value<int>("ink_items"));
            Assert.Equal(JTokenType.Null, row["ink_from_box_center_mm"].Type);
            Assert.Contains("ink_items_truncated", row["flags"].Values<string>());
            var gray = Assert.IsType<JObject>(row["gray"]);
            Assert.False(gray.Value<bool>("measured"));
            Assert.Contains("ink measurement limit", gray.Value<string>("why"));
            Assert.Null(gray["mean_darkness"]);

            // An explicit region does not depend on the truncated viewport bounds.
            Assert.True(PdfQaPaper.Gray(page, new[] { 1090.0, 790, 1140, 830 }).Value<bool>("measured"));
        }

        [Theory]
        [InlineData("BT /F1 10 Tf 1120 810 Td (Note) Tj ET", "text")]
        [InlineData("q 10 0 0 10 1120 810 cm BI /W 1 /H 1 /BPC 8 /CS /G /F /AHx ID FF> EI Q", "image")]
        public void The_mark_limit_withholds_gray_when_text_or_image_bounds_are_omitted(string omittedContent, string kind)
        {
            var content = new StringBuilder();
            for (int i = 0; i < 20000; i++) content.Append("1100 800 m 1110 810 l\n");
            content.Append("S\n").Append(omittedContent);
            var page = ReadContentStream(content.ToString(), captureDrawing: true);

            Assert.Single(page.Drawing);
            Assert.False(page.DrawingTruncated);
            Assert.Equal(2, page.Ink.Count);
            Assert.Equal(20000, page.Marks.Count);
            Assert.DoesNotContain(page.Marks, mark => mark.Kind == kind);
            Assert.True(page.MarksTruncated);
            Assert.Equal(kind == "text" ? 1 : 0, page.Words.Count);
            Assert.Equal(kind == "image" ? 1 : 0, page.Images);

            JObject gray = PdfQaPaper.Gray(page, new[] { 1090.0, 790, 1145, 830 });
            Assert.False(gray.Value<bool>("measured"));
            Assert.Contains("omitted text or image bounds", gray.Value<string>("why"));
            Assert.Null(gray["mean_darkness"]);
        }

        private static PdfPageFacts ReadContentStream(string content, bool captureDrawing = false)
        {
            string path = Temp();
            try
            {
                // A single PDF path operator must paint all subpaths together.
                string[] objects =
                {
                    "<< /Type /Catalog /Pages 2 0 R >>",
                    "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
                    FormattableString.Invariant($"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 {840 * Pt:F6} {594 * Pt:F6}] /Resources << /Font << /F1 << /Type /Font /Subtype /Type1 /BaseFont /Helvetica >> >> >> /Contents 4 0 R >>"),
                    $"<< /Length {content.Length + 1} >>\nstream\n{content}\nendstream"
                };
                var pdf = new StringBuilder("%PDF-1.4\n");
                var offsets = new List<int>();
                foreach (string obj in objects)
                {
                    offsets.Add(pdf.Length);
                    pdf.Append($"{offsets.Count} 0 obj\n{obj}\nendobj\n");
                }
                int xref = pdf.Length;
                pdf.Append("xref\n0 5\n0000000000 65535 f \n");
                foreach (int offset in offsets) pdf.Append(FormattableString.Invariant($"{offset:D10} 00000 n \n"));
                pdf.Append($"trailer\n<< /Size 5 /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n");
                File.WriteAllBytes(path, Encoding.ASCII.GetBytes(pdf.ToString()));
                return Assert.Single(PdfQa.Read(path, captureDrawing));
            }
            finally { if (File.Exists(path)) File.Delete(path); }
        }

        [Fact]
        public void With_paper_default_the_page_is_the_sheet()
        {
            double[] m = PdfQaPaper.SheetToPage(new[] { 0.0, 0, 420, 297 }, 420 * Pt, 297 * Pt);
            Assert.Equal(Pt, m[0], 6);
            Assert.Equal(0, m[1], 6);
            double[] offset = PdfQaPaper.SheetToPage(new[] { -10.0, -5, 410, 292 }, 420 * Pt, 297 * Pt);
            double[] back = PdfQaPaper.ToSheet(offset, PdfQaPaper.ToPage(offset, new[] { 0.0, 0, 100, 50 }));
            Assert.Equal(new[] { 0.0, 0, 100, 50 }, back.Select(v => Math.Round(v, 6)).ToArray());
            Assert.Equal(10 * Pt, PdfQaPaper.ToPage(offset, new[] { 0.0, 0, 1, 1 })[0], 6);
        }

        private static PdfPageFacts Page(params (string kind, double[] mm)[] marks)
        {
            var p = new PdfPageFacts { Page = 1, Width = 420 * Pt, Height = 297 * Pt };
            foreach (var m in marks) p.Marks.Add(new PdfMark { Kind = m.kind, Rect = m.mm.Select(v => v * Pt).ToArray() });
            p.Ink.AddRange(p.Marks.Select(x => x.Rect));
            p.Paths = p.Marks.Count(x => x.Kind == "path");
            return p;
        }

        [Fact]
        public void A_3d_view_printed_above_its_box_centre_is_measured_from_its_ink_not_its_box()
        {
            // Box 100..300 x 50..250 (centre 200,150); the drawing really sits 92 mm above the centre.
            PdfPageFacts page = Page(
                ("path", new[] { 150.0, 212, 250, 262 }),        // the 3D drawing, sticks 12 mm over the top
                ("text", new[] { 100.0, 40, 160, 46 }),          // the viewport title
                ("path", new[] { 5.0, 5, 415, 5.5 }),             // title block frame line: too long for any viewport
                ("path", new[] { 350.0, 50, 400, 60 }));          // something of the title block, far away
            var map = new PdfSheetMap { Page = 1, SheetId = 7, OutlineMm = new[] { 0.0, 0, 420, 297 } };
            map.Viewports.Add(new PdfViewportBox { ViewportId = 11, ViewId = 12, View = "3D", BoxMm = new[] { 100.0, 50, 300, 250 }, LabelMm = new[] { 98.0, 38, 162, 48 } });
            JObject row = (JObject)PdfQaPaper.ViewportInk(page, map)[0];
            Assert.Equal(1, row.Value<int>("ink_items"));
            Assert.Equal(1, row.Value<int>("label_ink_items"));
            Assert.Equal(new[] { 150.0, 212, 250, 262 }, row["ink_mm"].Select(t => t.Value<double>()).ToArray());
            Assert.Equal(new[] { 0.0, 87 }, row["center_offset_mm"].Select(t => t.Value<double>()).ToArray());
            Assert.Equal(new[] { -50.0, 62, 50, 112 }, row["ink_from_box_center_mm"].Select(t => t.Value<double>()).ToArray());
            Assert.Equal(162.0, row.Value<double>("max_difference_mm"));
            Assert.Equal(12.0, row["ink_minus_box_mm"].Value<double>("top"));
            Assert.Equal(new[] { "off_box", "overflows_box" }, row["flags"].Select(t => t.Value<string>()).ToArray());
        }

        [Fact]
        public void A_centred_drawing_has_no_flags_an_empty_view_is_flagged_and_the_report_lists_the_flagged()
        {
            PdfPageFacts page = Page(("path", new[] { 110.0, 60, 190, 140 }));
            var map = new PdfSheetMap { Page = 1, SheetId = 1, OutlineMm = new[] { 0.0, 0, 420, 297 } };
            map.Viewports.Add(new PdfViewportBox { ViewportId = 1, BoxMm = new[] { 100.0, 50, 200, 150 } });
            map.Viewports.Add(new PdfViewportBox { ViewportId = 2, BoxMm = new[] { 250.0, 50, 300, 100 } });
            JArray rows = PdfQaPaper.ViewportInk(page, map);
            Assert.Empty(rows[0]["flags"]);
            Assert.Equal("empty", rows[1]["flags"][0].Value<string>());
            var o = new PdfQaOptions { Viewports = true }; o.SheetMaps.Add(map);
            JArray flagged = (JArray)PdfQa.Judge(new[] { page }, o)["viewports"]["flagged"];
            Assert.Single(flagged);
            Assert.Equal(2, flagged[0].Value<long>("viewport_id"));
        }

        [Fact]
        public void Geometric_flags_are_withheld_on_an_approximate_page_and_the_row_says_so()
        {
            // The A3 sheet printed on A4 (scale 0.707): the position on the sheet is not exact.
            var a4 = new PdfPageFacts { Page = 1, Width = 297 * Pt, Height = 210 * Pt };
            a4.Marks.Add(new PdfMark { Kind = "path", Rect = new[] { 390.0, 290, 410, 310 } });
            a4.Ink.Add(a4.Marks[0].Rect); a4.Paths = 1;
            var map = new PdfSheetMap { Page = 1, SheetId = 1, OutlineMm = new[] { 0.0, 0, 420, 297 } };
            map.Viewports.Add(new PdfViewportBox { ViewportId = 3, BoxMm = new[] { 100.0, 50, 300, 250 } });
            JObject row = (JObject)PdfQaPaper.ViewportInk(a4, map)[0];
            Assert.Equal("approximate", row.Value<string>("flags_basis"));
            Assert.DoesNotContain(row["flags"], t => t.Value<string>() == "off_box" || t.Value<string>() == "overflows_box");
        }

        [Fact]
        public void Ink_at_the_page_edge_is_flagged_with_a_tolerance_in_mm_and_a_viewport_without_a_box_is_no_box()
        {
            double w = 420 * Pt, h = 297 * Pt;
            var page = new PdfPageFacts { Page = 1, Width = w, Height = h, Left = 10, Bottom = 20 };
            var rect = new[] { 10.0 + 0.3 * Pt, 100, 200, 300 };       // 0.3 mm inside the left edge of a page whose box starts at x=10
            page.Marks.Add(new PdfMark { Kind = "path", Rect = rect }); page.Ink.Add(rect); page.Paths = 1;
            var map = new PdfSheetMap { Page = 1, SheetId = 1, OutlineMm = new[] { 0.0, 0, 420, 297 } };
            map.Viewports.Add(new PdfViewportBox { ViewportId = 1, BoxMm = new[] { 0.0, 30, 100, 150 } });
            map.Viewports.Add(new PdfViewportBox { ViewportId = 2, BoxMm = null });
            JArray rows = PdfQaPaper.ViewportInk(page, map);
            Assert.Contains(rows[0]["flags"], t => t.Value<string>() == "touches_page_edge");
            Assert.Equal("no_box", rows[1]["flags"][0].Value<string>());
            // 2 mm inside: not at the edge.
            rect[0] = 10 + 2 * Pt;
            Assert.DoesNotContain(PdfQaPaper.ViewportInk(page, map)[0]["flags"], t => t.Value<string>() == "touches_page_edge");
        }

        [Fact]
        public void A_page_that_differs_only_in_letter_count_is_changed()
        {
            var a = new PdfPageFacts { Page = 1, Width = 595, Height = 842 }; a.Fonts["ArialMT"] = 100;
            var b = new PdfPageFacts { Page = 1, Width = 595, Height = 842 }; b.Fonts["ArialMT"] = 101;
            JObject r = PdfQaPaper.Compare(new[] { a }, new[] { b });
            Assert.Equal("changed", r.Value<string>("verdict"));
            Assert.Equal(1, r["pages"][0].Value<int>("letters_delta"));
        }

        [Fact]
        public void Compare_counts_letters_and_reports_stroke_deltas()
        {
            var a = new PdfPageFacts { Page = 1, Width = 595, Height = 842, Paths = 10, Segments = 40 };
            a.Fonts["ArialMT"] = 100;
            var b = new PdfPageFacts { Page = 1, Width = 595, Height = 842, Paths = 12, Segments = 55 };
            b.Fonts["ArialMT"] = 130;
            JObject page = (JObject)PdfQaPaper.Compare(new[] { a }, new[] { b })["pages"][0];
            Assert.Equal("changed", page.Value<string>("state"));
            Assert.Equal(30, page.Value<int>("letters_delta"));
            Assert.Equal(2, page.Value<int>("paths_delta"));
            Assert.Equal(15, page.Value<int>("segments_delta"));
        }

        [Fact]
        public void Ink_between_two_viewports_goes_to_the_nearest_box()
        {
            PdfPageFacts page = Page(("path", new[] { 205.0, 100, 207, 102 }));
            var map = new PdfSheetMap { Page = 1, OutlineMm = new[] { 0.0, 0, 420, 297 } };
            map.Viewports.Add(new PdfViewportBox { ViewportId = 1, BoxMm = new[] { 100.0, 50, 200, 150 } });
            map.Viewports.Add(new PdfViewportBox { ViewportId = 2, BoxMm = new[] { 210.0, 50, 300, 150 } });
            JArray rows = PdfQaPaper.ViewportInk(page, map);
            Assert.Equal(0, rows[0].Value<int>("ink_items"));
            Assert.Equal(1, rows[1].Value<int>("ink_items"));
        }

        [Fact]
        public void Judge_reports_viewports_only_when_asked_and_names_an_unprinted_sheet()
        {
            PdfPageFacts page = Page(("path", new[] { 120.0, 60, 180, 140 }));
            var o = new PdfQaOptions { Viewports = true };
            o.SheetMaps.Add(new PdfSheetMap { Page = 1, SheetId = 1, OutlineMm = new[] { 0.0, 0, 420, 297 }, Viewports = { new PdfViewportBox { ViewportId = 5, BoxMm = new[] { 100.0, 50, 200, 150 } } } });
            o.SheetMaps.Add(new PdfSheetMap { Page = 3, SheetId = 2, OutlineMm = new[] { 0.0, 0, 420, 297 } });
            JObject r = PdfQa.Judge(new[] { page }, o);
            Assert.Single((JArray)r["viewports"]["items"]);
            Assert.Equal(2, r["viewports"]["unmapped"][0].Value<long>("sheet_id"));
            Assert.Null(PdfQa.Judge(new[] { page }, new PdfQaOptions())["viewports"]);
        }

        [Fact]
        public void A_region_by_viewport_without_sheets_says_why_instead_of_measuring_nothing()
        {
            PdfPageFacts page = Page(("path", new[] { 120.0, 60, 180, 140 }));
            var o = PdfQa.Parse(JObject.Parse("{regions:[{name:'vp',viewport_id:5}]}"), out string e);
            Assert.Null(e);
            JObject region = (JObject)PdfQa.Judge(new[] { page }, o)["ink"][0]["regions"][0];
            Assert.False(region.Value<bool>("measured"));
            Assert.Contains("view_ids", region.Value<string>("why"));
            o.SheetMaps.Add(new PdfSheetMap { Page = 1, OutlineMm = new[] { 0.0, 0, 420, 297 }, Viewports = { new PdfViewportBox { ViewportId = 5, BoxMm = new[] { 100.0, 50, 200, 150 } } } });
            region = (JObject)PdfQa.Judge(new[] { page }, o)["ink"][0]["regions"][0];
            Assert.Equal(1, region.Value<int>("items"));
        }

        // ---- printed lines per note --------------------------------------------------------------

        [Fact]
        public void A_note_wrapped_by_revit_is_found_on_two_lines_and_flagged_against_one_expected()
        {
            var page = new PdfPageFacts { Page = 1, Width = 595, Height = 842 };
            page.Words.Add(new PdfWordFact { Text = "Otra", Left = 10, Bottom = 800, Right = 40, Top = 810 });
            page.Words.Add(new PdfWordFact { Text = "MURO", Left = 100, Bottom = 500, Right = 130, Top = 508 });
            page.Words.Add(new PdfWordFact { Text = "DE", Left = 133, Bottom = 500, Right = 145, Top = 508 });
            page.Words.Add(new PdfWordFact { Text = "CONCRETO,", Left = 100, Bottom = 489, Right = 160, Top = 497 });
            page.Words.Add(new PdfWordFact { Text = "e=15", Left = 163, Bottom = 489, Right = 185, Top = 497 });
            var note = new PdfNoteRequest { Text = "Muro de concreto, e=15", ExpectedLines = 1 };
            JObject row = PdfQaPaper.NoteLines(new[] { page }, note);
            Assert.True(row.Value<bool>("found"));
            Assert.Equal(2, row.Value<int>("lines"));
            Assert.Equal("MURO DE", row["line_texts"][0].Value<string>());
            Assert.False(row.Value<bool>("matches_expected"));
            var o = new PdfQaOptions(); o.Notes.Add(note);
            Assert.Equal("findings", PdfQa.Judge(new[] { page }, o).Value<string>("verdict"));
        }

        [Fact]
        public void A_note_not_on_the_page_is_not_found_and_says_so()
        {
            var page = new PdfPageFacts { Page = 1, Width = 595, Height = 842 };
            page.Words.Add(new PdfWordFact { Text = "MURO", Left = 100, Bottom = 500, Right = 130, Top = 508 });
            JObject row = PdfQaPaper.NoteLines(new[] { page }, new PdfNoteRequest { Text = "Losa" });
            Assert.False(row.Value<bool>("found"));
            Assert.NotNull(row.Value<string>("why"));
        }

        [Fact]
        public void A_real_pdf_note_on_two_lines_counts_two()
        {
            var builder = new PdfDocumentBuilder();
            var font = builder.AddStandard14Font(Standard14Font.Helvetica);
            PdfPageBuilder page = builder.AddPage(595, 842);
            page.AddText("IMPERMEABILIZACION CON", 8, new PdfPoint(100, 500), font);
            page.AddText("MANTO ASFALTICO", 8, new PdfPoint(100, 489), font);
            string path = Temp();
            try
            {
                File.WriteAllBytes(path, builder.Build());
                var o = PdfQa.Parse(JObject.Parse("{notes:[{text:'Impermeabilizacion con manto asfaltico', expected_lines:2}]}"), out string e);
                Assert.Null(e);
                JObject row = (JObject)PdfQa.Inspect(path, o)["notes"][0];
                Assert.True(row.Value<bool>("found"));
                Assert.Equal(2, row.Value<int>("lines"));
                Assert.True(row.Value<bool>("matches_expected"));
            }
            finally { if (File.Exists(path)) File.Delete(path); }
        }

        // ---- before / after ----------------------------------------------------------------------

        [Fact]
        public void Two_pdfs_are_compared_page_by_page_with_what_changed()
        {
            string before = Temp(), after = Temp();
            try
            {
                foreach (bool second in new[] { false, true })
                {
                    var builder = new PdfDocumentBuilder();
                    var font = builder.AddStandard14Font(Standard14Font.Helvetica);
                    PdfPageBuilder page = builder.AddPage(595, 842);
                    page.AddText(second ? "Detalle D-02" : "Detalle D-01", 12, new PdfPoint(100, 700), font);
                    page.DrawLine(new PdfPoint(100, 100), new PdfPoint(300, 100), 1);
                    if (second) page.DrawLine(new PdfPoint(100, 120), new PdfPoint(300, 120), 1);
                    File.WriteAllBytes(second ? after : before, builder.Build());
                }
                var o = PdfQa.Parse(JObject.Parse("{compare_to:" + JsonConvertString(before) + "}"), out string e);
                Assert.Null(e);
                JObject cmp = (JObject)PdfQa.Inspect(after, o)["comparison"];
                Assert.Equal("changed", cmp.Value<string>("verdict"));
                JObject p1 = (JObject)cmp["pages"][0];
                Assert.Contains("D-01", p1["words"]["removed"].Select(t => t.Value<string>()));
                Assert.Contains("D-02", p1["words"]["added"].Select(t => t.Value<string>()));
                Assert.Equal(1, p1["paths"][1].Value<int>() - p1["paths"][0].Value<int>());
                JObject self = (JObject)PdfQa.Inspect(before, o)["comparison"];
                Assert.Equal("same", self.Value<string>("verdict"));
            }
            finally { foreach (string f in new[] { before, after }) if (File.Exists(f)) File.Delete(f); }
        }

        private static string JsonConvertString(string s) => Newtonsoft.Json.JsonConvert.ToString(s);

