        [Fact]
        public void A_substituted_font_installed_for_this_user_only_advises_installing_it_for_all_users()
        {
            var page = new PdfPageFacts { Page = 1, Width = 100, Height = 100 };
            page.Fonts["ArialMT"] = 10;
            page.Words.Add(new PdfWordFact { Text = "x", Left = 10, Bottom = 10, Right = 20, Top = 20 });
            var o = new PdfQaOptions { ExpectedFonts = { "Arial Narrow" }, FontInventory = new Dictionary<string, string> { ["arialnarrow"] = "user" } };
            JObject fonts = (JObject)PdfQa.Judge(new[] { page }, o)["fonts"];
            JObject sub = (JObject)fonts["substituted"][0];
            Assert.Equal("user", sub.Value<string>("installed"));
            Assert.Contains("all users", sub.Value<string>("advice"));
            Assert.Equal("user", fonts["install_advice"][0].Value<string>("installed"));
            // Without an inventory nothing is claimed about installation.
            JObject plain = (JObject)PdfQa.Judge(new[] { page }, new PdfQaOptions { ExpectedFonts = { "Arial Narrow" } })["fonts"];
            Assert.Equal("unknown", plain["substituted"][0].Value<string>("installed"));
            Assert.Empty((JArray)plain["install_advice"]);
        }

