        private const double F = 1 / 304.8;

        [Fact]
        public void A_detail_number_already_on_the_sheet_is_found_without_case_and_null_is_refused()
        {
            var numbers = new[] { new KeyValuePair<long, string>(10, "1"), new KeyValuePair<long, string>(11, "A3") };
            Assert.Equal(11, PdfQaPaperHolder("A3", numbers));
            Assert.Equal(11, PdfQaPaperHolder("a3", numbers));
            Assert.Null(SheetPaperRules.Holder("2", numbers));
            Assert.Contains("already used", SheetPaperRules.DetailNumberRefusal("A3", "A-101", 11, "Detalle"));
            Assert.NotNull(SheetPaperRules.ValidateDetailNumber(new JValue("")));
            Assert.Null(SheetPaperRules.ValidateDetailNumber(new JValue("7")));
            Assert.Contains("null", SheetPaperRules.ValidateDetailNumber(JValue.CreateNull()));
            Assert.Null(SheetPaperRules.ValidateDetailNumber(null));
            Assert.Contains("null", SheetPaperRules.ValidateDetailNumber(JObject.Parse("{detail_number:null}")["detail_number"]));
        }

        [Fact]
