        private static long? PdfQaPaperHolder(string w, IEnumerable<KeyValuePair<long, string>> n) => SheetPaperRules.Holder(w, n)?.Key;

        [Fact]
        public void A_title_past_the_sheet_and_over_a_grid_head_is_warned_with_mm()
        {
            double[] sheet = { 0, 0, 420 * F, 297 * F };
            double[] label = { 400 * F, 10 * F, 430 * F, 18 * F };          // 10 mm past the right edge
            var heads = new[] { new DatumHead { DatumId = 3, Name = "A", ViewportId = 9, X = 405 * F, Y = 22 * F },   // 4 mm above: inside 6 mm
                                new DatumHead { DatumId = 4, Name = "B", ViewportId = 9, X = 300 * F, Y = 100 * F } };
            JObject c = SheetPaperRules.LabelCheck(label, sheet, heads);
            Assert.Equal("warning", c.Value<string>("state"));
            Assert.Equal(10.0, c["outside_mm"].Value<double>("right"), 1);
            Assert.Single((JArray)c["over_datum"]);
            Assert.Equal(3, c["over_datum"][0].Value<long>("datum_id"));
            Assert.Equal("ok", SheetPaperRules.LabelCheck(new[] { 100 * F, 10 * F, 130 * F, 18 * F }, sheet, heads).Value<string>("state"));
        }

        [Fact]
