            Assert.Equal(new[] { 150.0, 212, 250, 262 }, ink.Select(v => Math.Round(v * 304.8, 6)).ToArray());
            Assert.Null(SheetPaperRules.ValidateInkBox(JArray.Parse("[-50,62,50,112]")));
