        private static PdfQaOptions WithSheet(PdfSheetMap map) { var o = new PdfQaOptions { Viewports = true }; o.SheetMaps.Add(map); return o; }

        [Fact]
        public void A_viewport_with_no_ink_is_never_clean()
        {
            PdfPageFacts page = Page(("path", new[] { 120.0, 60, 180, 140 }));
            var map = new PdfSheetMap { Page = 1, SheetId = 1, OutlineMm = new[] { 0.0, 0, 420, 297 },
                Viewports = { new PdfViewportBox { ViewportId = 5, BoxMm = new[] { 100.0, 50, 200, 150 } }, new PdfViewportBox { ViewportId = 6, BoxMm = new[] { 250.0, 50, 350, 150 } } } };
            JObject r = PdfQa.Judge(new[] { page }, WithSheet(map));
            Assert.Equal("partial", r.Value<string>("verdict"));
            Assert.Contains(r["incomplete"], t => t.Value<string>().Contains("viewport 6"));
            JObject empty = (JObject)r["viewports"]["items"][1];
            Assert.False(empty.Value<bool>("ink_found"));
            Assert.NotNull(empty.Value<string>("why"));
        }

        [Fact]
        public void An_unmapped_sheet_says_why_and_makes_the_verdict_partial()
        {
            PdfPageFacts page = Page(("path", new[] { 120.0, 60, 180, 140 }));
            var map = new PdfSheetMap { Page = 1, SheetId = 9, OutlineWhy = "the outline of sheet A-1 could not be read: boom" };
            JObject r = PdfQa.Judge(new[] { page }, WithSheet(map));
            Assert.Equal("partial", r.Value<string>("verdict"));
            Assert.Contains("boom", r["viewports"]["unmapped"][0].Value<string>("why"));
            Assert.Contains(r["incomplete"], t => t.Value<string>().Contains("boom"));
            var noPage = new PdfSheetMap { Page = 4, SheetId = 2, OutlineMm = new[] { 0.0, 0, 420, 297 } };
            Assert.Equal("partial", PdfQa.Judge(new[] { page }, WithSheet(noPage)).Value<string>("verdict"));
        }

        [Fact]
        public void A_region_that_could_not_be_measured_makes_the_verdict_partial()
        {
            PdfPageFacts page = Page(("path", new[] { 120.0, 60, 180, 140 }));
            var o = PdfQa.Parse(JObject.Parse("{regions:[{name:'vp',viewport_id:5}]}"), out string e);
