        [Fact]
        public void A_page_printed_at_the_sheet_size_maps_exactly_and_a_scaled_one_is_approximate()
        {
            PdfPageFacts a3 = Page(("text", new[] { 380.0, 10, 400, 15 }));
            a3.Words.Add(new PdfWordFact { Text = "A-101", Left = 380 * Pt, Bottom = 10 * Pt, Right = 400 * Pt, Top = 15 * Pt });
            var map = new PdfSheetMap { Page = 1, SheetId = 1, SheetNumber = "A-101", OutlineMm = new[] { 0.0, 0, 420, 297 } };
            JObject exact = PdfQaPaper.Mapping(a3, map, out double[] m, out bool isExact);
            Assert.True(isExact);
            Assert.Equal("exact", exact.Value<string>("mapping"));
            Assert.Equal(2.8346, exact.Value<double>("scale_pt_per_mm"), 4);
            Assert.False(exact.Value<bool>("page_order_unverified"));

            // The same A3 sheet printed on A4: scale 0.707, the assumption is named and anchor=ink is not offered.
            var a4 = new PdfPageFacts { Page = 1, Width = 297 * Pt, Height = 210 * Pt };
            a4.Marks.Add(new PdfMark { Kind = "path", Rect = new[] { 390.0, 290, 410, 310 } });
            a4.Ink.Add(a4.Marks[0].Rect); a4.Paths = 1;
            map.Viewports.Add(new PdfViewportBox { ViewportId = 3, BoxMm = new[] { 100.0, 50, 300, 250 } });
            JObject approx = PdfQaPaper.Mapping(a4, map, out m, out isExact);
            Assert.False(isExact);
            Assert.Equal("approximate", approx.Value<string>("mapping"));
            Assert.True(approx.Value<bool>("page_order_unverified"));
            JObject row = (JObject)PdfQaPaper.ViewportInk(a4, map)[0];
            Assert.Equal(JTokenType.Null, row["ink_from_box_center_mm"].Type);
            Assert.Contains("approximate", row.Value<string>("ink_anchor"));
            JObject judged = PdfQa.Judge(new[] { a4 }, WithSheet(map));
            Assert.Equal("partial", judged.Value<string>("verdict"));
            Assert.Contains(judged["incomplete"], t => t.Value<string>().Contains("approximate"));
        }

        [Fact]
