        }

        private static PdfWordFact W(string t, double l, double b, double r) => new PdfWordFact { Text = t, Left = l, Bottom = b, Right = r, Top = b + 8 };

        [Fact]
        public void The_same_text_printed_twice_is_ambiguous_not_a_line_count()
        {
            var page = new PdfPageFacts { Page = 1, Width = 595, Height = 842 };
            page.Words.Add(W("VER", 100, 500, 120)); page.Words.Add(W("DETALLE", 123, 500, 160));
            page.Words.Add(W("VER", 300, 200, 320)); page.Words.Add(W("DETALLE", 323, 200, 360));
            var note = new PdfNoteRequest { Text = "Ver detalle", ExpectedLines = 1 };
            JObject row = PdfQaPaper.NoteLines(new[] { page }, note);
            Assert.True(row.Value<bool>("ambiguous"));
            Assert.Equal(2, row.Value<int>("candidates"));
            Assert.Null(row["lines"]);
            Assert.Null(row["matches_expected"]);
            var o = new PdfQaOptions(); o.Notes.Add(note);
            Assert.Equal("partial", PdfQa.Judge(new[] { page }, o).Value<string>("verdict"));
        }

        [Fact]
        public void A_match_that_goes_on_along_its_line_is_part_of_another_note()
        {
            var page = new PdfPageFacts { Page = 1, Width = 595, Height = 842 };
            page.Words.Add(W("VER", 100, 500, 120)); page.Words.Add(W("DETALLE", 123, 500, 160)); page.Words.Add(W("3", 163, 500, 170));
            JObject row = PdfQaPaper.NoteLines(new[] { page }, new PdfNoteRequest { Text = "Ver detalle" });
            Assert.False(row.Value<bool>("found"));
            page.Words.Add(W("VER", 100, 300, 120)); page.Words.Add(W("DETALLE", 123, 300, 160));
            row = PdfQaPaper.NoteLines(new[] { page }, new PdfNoteRequest { Text = "Ver detalle" });
            Assert.True(row.Value<bool>("found"));
            Assert.False(row.Value<bool>("ambiguous"));
        }

        [Fact]
        public void A_note_by_id_is_searched_only_inside_its_own_box()
        {
            // Two notes with the same text on an A3 page; the note asked for sits at 100..150 x 102..110 mm of the sheet.
